import {useState} from 'react';
import type {TurnoverList} from '@/lib/turnovers';
import {planTurnoverAssignments} from '@/lib/turnover-assignment-plan';
export function TurnoverAssignmentPlanner({data,disabled,onReview}:{data:TurnoverList;disabled:boolean;onReview?:(plan:ReturnType<typeof planTurnoverAssignments>|null,reason:string)=>void}){
 const [selected,setSelected]=useState<Record<string,boolean>>({}),[limits,setLimits]=useState<Record<string,string>>({});
 const [plan,setPlan]=useState<ReturnType<typeof planTurnoverAssignments>|null>(null),[error,setError]=useState(''),[reason,setReason]=useState('');
 if(!data.can_manage)return null;
 const label=(id:string)=>data.eligible_assignees.find(p=>p.user_id===id)?.label??id;
 return <details><summary>Plan cleaning assignments</summary><p>Release preview: preview first, then prepare and save the reviewed assignments. Previewing alone does not save or notify staff.</p><form onSubmit={e=>{e.preventDefault();setError('');setPlan(null);onReview?.(null,'');try{setPlan(planTurnoverAssignments(data,data.eligible_assignees.filter(p=>selected[p.user_id]).map(p=>({userId:p.user_id,maximumTasks:Number(limits[p.user_id]??'')}))))}catch(cause){setError(cause instanceof Error?cause.message:'Unable to plan assignments.')}}}>
 <fieldset disabled={disabled}><legend>Select available cleaners and total task limits</legend>{data.eligible_assignees.map(p=><div key={p.user_id} style={{display:'flex',flexWrap:'wrap',gap:16,alignItems:'center',marginBlock:12}}><label><input type="checkbox" checked={!!selected[p.user_id]} onChange={e=>{setSelected({...selected,[p.user_id]:e.target.checked});setPlan(null);onReview?.(null,'')}}/> {p.label}</label>{selected[p.user_id]&&<label className="field">Task limit for {p.label}<input type="number" min={1} max={100} step={1} required value={limits[p.user_id]??''} onChange={e=>{setLimits({...limits,[p.user_id]:e.target.value});setPlan(null);onReview?.(null,'')}}/></label>}</div>)}<button className="secondary" type="submit">Preview assignments</button></fieldset></form>
 {error&&<p role="alert">{error}</p>}{plan&&<section aria-label="Proposed cleaning assignments"><p>{plan.assignments.length} proposed assignments. {plan.unallocated.length} eligible tasks remain unallocated because the selected team has no remaining capacity.</p><ul>{plan.loads.map(p=><li key={p.userId}>{label(p.userId)}: {p.existing} existing + {p.proposed} proposed / {p.maximumTasks} task limit</li>)}</ul><ol>{plan.assignments.map(a=><li key={a.taskId}>Room {a.roomLabel}: {label(a.assigneeId)}</li>)}</ol>{onReview&&plan.assignments.length>0&&<form onSubmit={e=>{e.preventDefault();onReview(plan,reason.trim())}}><label className="field">Assignment plan reason<input value={reason} minLength={4} maxLength={500} required disabled={disabled} onChange={e=>{setReason(e.target.value);onReview(null,'')}}/></label><button className="secondary" disabled={disabled||plan.assignments.length>500}>Prepare reviewed batch</button>{plan.assignments.length>500&&<p>A batch supports up to 500 tasks. Reduce team limits before preparing.</p>}</form>}{!plan.assignments.length&&<p>No assignments proposed. Review unassigned due work, blockers and team limits.</p>}</section>}
 <p>Limits include all existing queued and in-progress tasks. Only unassigned, unblocked, vacant queued work due today or earlier is proposed, oldest due first. Staff with the lowest used fraction of their limit receive work first. Task counts do not estimate cleaning effort or shift hours. Refreshing the queue clears this proposal.</p></details>;
}
